            foreach(var field in type.GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.DeclaredOnly).OrderBy(f=>f.Name,StringComparer.Ordinal))if(field.Name!="tacticalPassiveIncome")method.Invoke(null,new object[]{w,field.FieldType,field.GetValue(value)});
